# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">İKİ KAT AÇI (YARIM AÇI) İLERİ UYGULAMALARI: ZİNCİR ÇARPIM VE BİR YOK ETME (12.3.1.2)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. Kosinüs Zincir Çarpımları</text>\n  <text x="32" y="92" font-size="10.5" fill="#1e3a8a">• Açıları ikişer katına çıkan kosinüs</text>\n  <text x="40" y="107" font-size="10.5" fill="#1e3a8a">çarpımlarında ifade <tspan font-weight="bold">2·sin(en küçük açı)</tspan></text>\n  <text x="40" y="122" font-size="10.5" fill="#1e3a8a">ile çarpılıp bölünür:</text>\n  <rect x="32" y="134" width="296" height="48" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="180" y="152" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">P = cos(x) · cos(2x) · cos(4x)</text>\n  <text x="180" y="170" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e40af">P = sin(8x) / [8·sin(x)]</text>\n  <text x="32" y="202" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Kare alma özdeşliği:</tspan></text>\n  <text x="40" y="220" font-size="10.5" font-weight="bold" fill="#1d4ed8">(sin x ± cos x)² = 1 ± sin(2x)</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">2. "1" Sayısını Yok Etme ve Yarım Açı</text>\n  <rect x="372" y="82" width="296" height="44" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="520" y="100" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">1 + cos(2x) = 2·cos²(x)</text>\n  <text x="520" y="117" text-anchor="middle" font-size="10" fill="#14532d">("+1" varsa cos(2x) = 2·cos²(x) − 1 seçilir)</text>\n  <rect x="372" y="134" width="296" height="44" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="520" y="152" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">1 − cos(2x) = 2·sin²(x)</text>\n  <text x="520" y="169" text-anchor="middle" font-size="10" fill="#14532d">("−1" varsa cos(2x) = 1 − 2·sin²(x) seçilir)</text>\n  <rect x="372" y="186" width="296" height="42" rx="6" fill="#f0fdf4" stroke="#16a34a"/>\n  <text x="520" y="204" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">Özel Oran: [1 − cos(2x)] / sin(2x) = tan(x)</text>\n  <text x="520" y="220" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">[1 + cos(2x)] / sin(2x) = cot(x)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">YARIM AÇI DİK ÜÇGEN YÖNTEMİ (2x\'ten x\'e Geçiş) VE TERS FONKSİYONLAR</text>\n  <rect x="20" y="46" width="340" height="194" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="190" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">2x Açısından x Açısına İkizkenar Üçgenle Geçiş</text>\n  <polygon points="50,195 290,195 290,95" fill="#ffffff" stroke="#b45309" stroke-width="2"/>\n  <line x1="185" y1="195" x2="290" y2="95" stroke="#dc2626" stroke-width="2"/>\n  <rect x="278" y="183" width="12" height="12" fill="none" stroke="#b45309" stroke-width="1.5"/>\n  <text x="82" y="190" font-size="11" font-weight="bold" fill="#92400e">x</text>\n  <text x="204" y="190" font-size="11" font-weight="bold" fill="#dc2626">2x</text>\n  <text x="273" y="122" font-size="10.5" font-weight="bold" fill="#dc2626">x</text>\n  <text x="115" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">c (hipotenüs kadar uzat)</text>\n  <text x="237" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">b</text>\n  <text x="302" y="150" font-size="11" font-weight="bold" fill="#78350f">a</text>\n  <text x="225" y="138" font-size="11" font-weight="bold" fill="#dc2626">c</text>\n  <text x="190" y="230" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#92400e">tan(2x) = a/b ve c = kök(a²+b²) ise → cot(x) = (b+c)/a</text>\n  <rect x="375" y="46" width="305" height="194" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="527" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">Ters Trigonometrik İfadelerde Yarım Açı</text>\n  <rect x="388" y="84" width="278" height="65" rx="6" fill="#ffffff" stroke="#c084fc"/>\n  <text x="527" y="103" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">Örnek Tip 1: sin(2 · arctan(3/4))</text>\n  <text x="527" y="120" text-anchor="middle" font-size="10" fill="#581c87">arctan(3/4) = α denirse tan(α) = 3/4 olur.</text>\n  <text x="527" y="136" text-anchor="middle" font-size="10" font-weight="bold" fill="#6b21a8">sin(2α) = 2·sin(α)·cos(α) = 2·(3/5)·(4/5) = 24/25</text>\n  <rect x="388" y="158" width="278" height="68" rx="6" fill="#ffffff" stroke="#c084fc"/>\n  <text x="527" y="177" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">Örnek Tip 2: cos(2 · arcsin(1/3))</text>\n  <text x="527" y="194" text-anchor="middle" font-size="10" fill="#581c87">arcsin(1/3) = θ denirse sin(θ) = 1/3 olur.</text>\n  <text x="527" y="211" text-anchor="middle" font-size="10" font-weight="bold" fill="#6b21a8">cos(2θ) = 1 − 2·sin²(θ) = 1 − 2·(1/9) = 7/9</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">TRİGONOMETRİK DENKLEMLERE GİRİŞ: sin(x) = a VE cos(x) = a (12.3.2.1)</text>\n  <rect x="20" y="46" width="320" height="194" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">1. sin(f(x)) = sin(α) Denklemi</text>\n  <text x="32" y="92" font-size="10.5" fill="#1e3a8a">• |a| ≤ 1 olmak üzere sin(x) = a = sin(α) ise</text>\n  <text x="40" y="107" font-size="10.5" fill="#1e3a8a">birim çemberde sinüsü aynı olan açılar</text>\n  <text x="40" y="122" font-size="10.5" font-weight="bold" fill="#1d4ed8">α ve (π − α) [yani 180° − α] açılarıdır:</text>\n  <rect x="32" y="134" width="296" height="58" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="180" y="154" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">x₁ = α + 2kπ   (α + 360°·k)</text>\n  <text x="180" y="176" text-anchor="middle" font-size="11" font-weight="bold" fill="#dc2626">x₂ = (π − α) + 2kπ   (180° − α + 360°·k)</text>\n  <text x="180" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e3a8a">(k ∈ Z tam sayı · Periyot T = 2π)</text>\n  <rect x="360" y="46" width="320" height="194" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">2. cos(f(x)) = cos(α) Denklemi</text>\n  <text x="372" y="92" font-size="10.5" fill="#7f1d1d">• |a| ≤ 1 olmak üzere cos(x) = a = cos(α) ise</text>\n  <text x="380" y="107" font-size="10.5" fill="#7f1d1d">birim çemberde kosinüsü aynı olan açılar</text>\n  <text x="380" y="122" font-size="10.5" font-weight="bold" fill="#b91c1c">α ve (−α) [veya 2π − α] açılarıdır:</text>\n  <rect x="372" y="134" width="296" height="58" rx="6" fill="#ffffff" stroke="#f87171"/>\n  <text x="520" y="154" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">x₁ = α + 2kπ   (α + 360°·k)</text>\n  <text x="520" y="176" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">x₂ = −α + 2kπ   (−α + 360°·k)</text>\n  <text x="520" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#991b1b">|a| &gt; 1 ise Çözüm Kümesi ÇK = ∅ (Boş Küme)!</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
